-- ════════════════════════════════════════════════════════════════════════
-- 0048 — La transcodifica delle paline dell'AVM (tappa 6.20)
-- ────────────────────────────────────────────────────────────────────────
-- Le fermate hanno due numerazioni: quella dell'AVM (il flusso SIRI) e lo
-- stop_id del feed GTFS, e i due numeri si sovrappongono. La tabella che le
-- mette in corrispondenza era un file dentro il codice
-- (artifacts/api-server/data/transcodifica-paline-mizar.csv, 4.400 righe di
-- Conerobus del 13 aprile 2026). Qui diventa un dato dell'azienda:
--   transcodifica_paline  palina (il codice dell'AVM), stop_id del feed (vuoto
--                         se il file non ne dava uno valido, e allora in
--                         codice_file resta quello che c'era, per esempio
--                         «new_CT»), il nome, l'ordine delle righe, quando è
--                         stata importata e da chi.
-- La sostituisce per intero l'amministratore, importando un CSV nello stesso
-- formato del file (mizar_ref,stop_id,nome). Le correzioni dell'operatore
-- restano dove sono (caronte.stop_alias_overrides) e valgono sopra questa.
-- Per Conerobus entrano le righe del file, nello stesso ordine.
-- Un'installazione nuova parte vuota.
-- ════════════════════════════════════════════════════════════════════════
DO $paline$
BEGIN
  IF pg_catalog.to_regclass('public.transcodifica_paline') IS NULL THEN
    CREATE TABLE public.transcodifica_paline (
      palina        text PRIMARY KEY CONSTRAINT transcodifica_paline_palina CHECK (palina ~ '^[0-9A-Za-z_.:-]{1,40}$'),
      -- lo stop_id del feed; vuoto: la palina non ha (ancora) una fermata nel feed
      stop_id       text CONSTRAINT transcodifica_paline_stop_id CHECK (stop_id ~ '^[0-9A-Za-z_.:-]{1,64}$' AND stop_id !~ '^[Nn][Ee][Ww]_'),
      -- quello che c'era al posto di uno stop_id valido, per chi tiene la tabella
      codice_file   text CONSTRAINT transcodifica_paline_codice_file CHECK (char_length(codice_file) <= 64 AND codice_file !~ '[[:cntrl:]]'),
      nome          text CONSTRAINT transcodifica_paline_nome CHECK (char_length(nome) <= 200 AND nome !~ '[[:cntrl:]]'),
      ordine        integer NOT NULL CONSTRAINT transcodifica_paline_ordine CHECK (ordine BETWEEN 1 AND 1000000),
      importata_il  timestamptz NOT NULL DEFAULT now(),
      importata_da  uuid REFERENCES public.users(id) ON DELETE SET NULL,
      CONSTRAINT transcodifica_paline_codice CHECK (stop_id IS NULL OR codice_file IS NULL)
    );
  END IF;
  IF pg_catalog.to_regrole('cerbero_owner') IS NOT NULL THEN
    ALTER TABLE public.transcodifica_paline OWNER TO cerbero_owner;
  END IF;
END $paline$;
--> statement-breakpoint
SELECT registro.sorveglia('public.transcodifica_paline', ARRAY['palina'], NULL, NULL, true, '{}', ARRAY['importata_il']);
--> statement-breakpoint
-- I dati come cerbero_owner, solo se le tabelle che si toccano sono già sue
-- e se può già usare lo schema (dove public non è aperto a tutti, il permesso
-- lo dà il riallineamento dei ruoli, dopo le migrazioni).
DO $come$ BEGIN
  IF pg_catalog.to_regrole('cerbero_owner') IS NOT NULL THEN
    IF pg_catalog.has_schema_privilege('cerbero_owner', 'public', 'USAGE')
       AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
                        WHERE c.oid IN (pg_catalog.to_regclass('public.azienda'), pg_catalog.to_regclass('public.transcodifica_paline'))
                          AND c.relowner IS DISTINCT FROM pg_catalog.to_regrole('cerbero_owner')) THEN
      EXECUTE 'SET LOCAL ROLE cerbero_owner';
    END IF;
  END IF;
END $come$;
--> statement-breakpoint
